command:
pnpm --filter @iris/runtime exec vitest run \
  src/phase55-security-acceptance.test.ts \
  src/phase3-shell-jobs.test.ts \
  src/phase7-security-acceptance.test.ts \
  src/phase7-external-integration.test.ts \
  src/multi-worker/observability.test.ts \
  src/multi-worker/security-acceptance.test.ts
pnpm --filter @iris/runtime exec tsx -e '
  import { redactOutput, StreamingRedactor } from "./src/output-redaction.ts";
  const secret = "SYNTHETIC_REDACTION_MARKER_4b9c6a8f";
  const stream = new StreamingRedactor([secret]);
  const output = [
    redactOutput(`Authorization: Bearer ${secret}`, [secret]),
    redactOutput(`API_TOKEN=${secret}`, [secret]),
    stream.push(`prefix ${secret.slice(0, 12)}`) + stream.push(`${secret.slice(12)} suffix`) + stream.finish(),
  ].join("\n");
  if (output.includes(secret)) throw new Error("Synthetic redaction marker leaked");
'

node --input-type=module <<'JS'
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
const patterns = {
  privateKey: /-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----/,
  githubToken: /\b(?:gh[pousr]_[A-Za-z0-9]{30,}|github_pat_[A-Za-z0-9_]{30,})\b/,
  awsAccessKey: /\b(?:AKIA|ASIA)[A-Z0-9]{16}\b/,
  openaiKey: /\bsk-(?:proj-)?[A-Za-z0-9_-]{32,}\b/,
};
const findSecrets = diff => {
  const added = diff.split('\n').filter(line => line.startsWith('+') && !line.startsWith('+++')).map(line => line.slice(1)).join('\n');
  return Object.entries(patterns).filter(([, pattern]) => pattern.test(added)).map(([name]) => name);
};
const synthetic = ['-----BEGIN ' + 'PRIVATE KEY-----', 'ghp_' + 'A'.repeat(32), 'AKIA' + 'A'.repeat(16), 'sk-' + 'a'.repeat(40)];
assert.deepEqual(findSecrets(synthetic.map(value => '+' + value).join('\n')), Object.keys(patterns));
assert.deepEqual(findSecrets('+++ b/example.ts\n+const count = 1;'), []);
const diff = execFileSync('git', ['diff', '--unified=0', process.env.BASELINE_SHA, process.env.TARGET_SHA], { encoding: 'utf8', maxBuffer: 8 * 1024 * 1024 });
const matches = findSecrets(diff);
if (matches.length) throw new Error(`Secret-pattern match in added source: ${matches.join(', ')}`);
console.log('Bounded added-lines secret-pattern scan and synthetic self-check PASS (not exhaustive secret detection)');
JS
